```typescript
import * as THREE from 'three';

class CameraController {
  private camera: THREE.PerspectiveCamera;
  private target: THREE.Vector3;
  private controls: THREE.OrbitControls;

  constructor(camera: THREE.PerspectiveCamera, target: THREE.Vector3) {
    this.camera = camera;
    this.target = target;

    const orbitControls = new THREE.OrbitControls(this.camera, null);
    orbitControls.target.set(this.target.x, this.target.y, this.target.z);
    orbitControls.update(); // Initial update

    this.controls = orbitControls;
  }

  public update(): void {
    this.controls.update();
  }

  public getCameraPosition(): THREE.Vector3 {
    return this.camera.position;
  }

  public setTargetPosition(position: THREE.Vector3): void {
    this.target.set(position.x, position.y, position.z);
    this.controls.target.set(this.target.x, this.target.y, this.target.z);
  }
}
```

