QImage matrixToImage(const Eigen::MatrixXd& matrix, int width, int height) {
    QImage image(width, height, QImage::Format_RGB32);

    for (int i = 0; i < width * height; ++i) {
        double value = matrix(i / width, i % width); // Assuming row-major order
        QRGB color;

        // Map the matrix value to an RGB color
        if (value > 0.0) {
            color = qRgb(value * 255.0, value * 255.0, value * 255.0);
        } else {
            color = qRgb(0, 0, 0); // Black for negative values or zeros
        }

        image.setPixelColor(i % width, i / width, color);
    }

    return image;
}
