```cpp
#include <iostream>
#define ARRAY_SIZE 7 // Maximum size of the array

void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
