    [HttpGet("GetUsernameFromJwt")]
    public ActionResult<string> GetUsernameFromJwt(string jwtToken)
    {
        try
        {
            // HERE: Validate the JWT token
            JwtSecurityToken validJwt = ValidateJwtToken(jwtToken);

            // Extract user name from the JWT claims
            string username = validJwt.Claims.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;

            if (!String.IsNullOrEmpty(username))
                return Ok(username);
            else
                return BadRequest("Username not found in the JWT token.");
        }
        catch (Exception ex)
        {
            return BadRequest($"Failed to validate JWT token: {ex.Message}");
        }
    }

