    for (size_t i = 0; i < argc; ++i) {
        current_length += strlen(argv[i]) + 1; // Add space between arguments
        total_length += current_length;
    }

    // Allocate memory for the result string and copy arguments into it
    result = malloc(total_length);
    if (!result) {
        fprintf(stderr, "Out of memory\n");
        return EXIT_FAILURE;
