 Here's the code for the `RedisClient.js` file inside the `utils` folder:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => console.error(`Error connecting to Redis: ${err}`));
  }

  async isAlive() {
    return new Promise((resolve, reject) => {
      this.client.ping((err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply === 'PONG');
        }
      });
    });
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, result) => {
        if (err) {
          reject(err);
        } else {
          resolve(result);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This `RedisClient` class initializes a new Redis client and sets up an error event listener. It also defines the `isAlive`, `get`, `set`, and `del` methods with their respective functionality. All methods are asynchronous and return Promises. Finally, it exports an instance of the `RedisClient` class named `redisClient`.

